			}),
			tailwindcss(),
			tanstackStart(),
			tanstackStartVitePlusDevMiddleware(),
			viteReact(),
			vanillaExtractPlugin(),
		]),
		test: {
			environment: 'jsdom',
			include: ['src/**/*.test.{ts,tsx}'],
		},
	});
};

